#!/bin/zsh
# Saison 2, chapitre 16 : 2e passe (héros assis avec LE seau retenu en 2e référence ; élève à la carotte d'après l'élève retenu ;
# boucles LTX de la chauve-souris et de la chouette).
cd "$(dirname "$0")/.." || exit 1
HS="${HS:-work/crossover/hero_s2}"; P=work/s2play/persos
for sd in 3 4; do out="$P/hero_sort16_$sd.png"; [ -f "$out" ] || flux-image "Exactly the same character as in the first reference picture, same face, same horned iron helmet, same armor, kilt and boots, now sitting on a small four-legged wooden stool, hands on his knees, a proud happy smile; exactly the same wide old wooden bucket with dark iron bands and the same grumpy talking face as in the second reference picture is perched upright on top of his helmet between the horns, the bucket is as wide as his shoulders; seen from the front. The whole figure visible with a margin, plain flat solid magenta background, no shadow, no ground, no text." -i $HS/sel_front.png -i $P/bucket16_1.png -s 1024x1280 --seed $(( 1610 + sd )) -o "$out"; done
for sd in 1 2; do out="$P/student16c_$sd.png"; [ -f "$out" ] || flux-image "Exactly the same teenage student as in the reference picture, same face, same red hair and freckles, same black robe, same pose and same raised right hand, but the thin magic wand in his raised hand is now a long orange carrot with green leaves at its end, he looks at it puzzled and disgusted. The whole figure visible with a margin, plain flat solid magenta background, no shadow, no ground, no text." -i $P/student16_1.png -s 1024x1280 --seed $(( 1660 + sd )) -o "$out"; done
FIX="CAMERA: static locked-off full shot, the camera never moves, no zoom."
MAG="It keeps exactly the same viewing angle and the same look for the whole shot. ENV: plain flat solid magenta background, perfectly uniform, no ground, no shadow, no scenery."
l(){ out="work/s2play/ltx/$1.mp4"; [ -f "$out" ] || video-locale "$FIX SUBJECT: $2 ACTION: $3 $MAG" -o "$out" -d $4 -s 768x960 -i "$5" -i "$5" --seed $6 -- --no-audio >/dev/null 2>&1 && echo "ok $1"; }
l bat16_i "the small black bat of the image with a sour human face." "it hovers in place, flapping its leathery wings steadily up and down, its sour face keeps the same contemptuous expression and stays turned to the camera, it does not move away, then it comes back to the starting pose." 2 $P/bat16_1.png 1711
l owl16_i "the barn owl of the image on its wooden perch." "it stays perched in place, alive: it blinks slowly, tilts its head a little to one side and back, ruffles its feathers once, the perch does not move, then it comes back to the starting pose." 3 $P/owl16_1.png 1712
echo fini
